import{_ as e,o as a,c as n,ag as o}from"./chunks/framework.1IVNT0ce.js";const F=JSON.parse('{"title":"Event Reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/events.md","filePath":"reference/events.md"}'),l={name:"reference/events.md"};function t(p,s,r,c,i,d){return a(),n("div",null,[...s[0]||(s[0]=[o(`<h1 id="event-reference" tabindex="-1">Event Reference <a class="header-anchor" href="#event-reference" aria-label="Permalink to &quot;Event Reference&quot;">​</a></h1><p>Klix uses a simple ordered event bus. This page lists the lifecycle events that the current runtime emits and explains the expected handler shapes.</p><p>For guide-level examples, see <a href="./../guides/handling-events">Handling Events</a>.</p><h2 id="registering-a-listener" tabindex="-1">Registering A Listener <a class="header-anchor" href="#registering-a-listener" aria-label="Permalink to &quot;Registering A Listener&quot;">​</a></h2><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#89DDFF;">@</span><span style="color:#82AAFF;">app</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">on</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">start</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#C792EA;">def</span><span style="color:#82AAFF;"> on_start</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">session</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">Session</span><span style="color:#89DDFF;">)</span><span style="color:#89DDFF;"> -&gt;</span><span style="color:#89DDFF;"> None:</span></span>
<span class="line"><span style="color:#BABED8;">    session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">ui</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">print</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Ready.</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> color</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">accent</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span></code></pre></div><p>Listeners can be sync or async.</p><h2 id="events-emitted-by-the-main-app-loop" tabindex="-1">Events Emitted By The Main App Loop <a class="header-anchor" href="#events-emitted-by-the-main-app-loop" aria-label="Permalink to &quot;Events Emitted By The Main App Loop&quot;">​</a></h2><h3 id="start" tabindex="-1"><code>start</code> <a class="header-anchor" href="#start" aria-label="Permalink to &quot;\`start\`&quot;">​</a></h3><p>Emitted after the session, renderer, input engine, and UI are ready.</p><p>Typical handler arguments:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#C792EA;">def</span><span style="color:#82AAFF;"> on_start</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">session</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">Session</span><span style="color:#89DDFF;">)</span><span style="color:#89DDFF;"> -&gt;</span><span style="color:#89DDFF;"> None:</span></span>
<span class="line"><span style="color:#BABED8;">    ...</span></span></code></pre></div><p>Use it for:</p><ul><li>initial layout setup</li><li>welcome messages</li><li>startup summaries</li></ul><h3 id="input" tabindex="-1"><code>input</code> <a class="header-anchor" href="#input" aria-label="Permalink to &quot;\`input\`&quot;">​</a></h3><p>Emitted when raw input is received from the prompt loop.</p><p>Handler shape:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#C792EA;">def</span><span style="color:#82AAFF;"> on_input</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">text</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> str</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> session</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">Session</span><span style="color:#89DDFF;">)</span><span style="color:#89DDFF;"> -&gt;</span><span style="color:#89DDFF;"> None:</span></span>
<span class="line"><span style="color:#BABED8;">    ...</span></span></code></pre></div><p>Use it for:</p><ul><li>counters</li><li>logging</li><li>telemetry</li></ul><h3 id="command" tabindex="-1"><code>command</code> <a class="header-anchor" href="#command" aria-label="Permalink to &quot;\`command\`&quot;">​</a></h3><p>Emitted when a command has been parsed and is about to execute.</p><p>Handler shape:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#C792EA;">def</span><span style="color:#82AAFF;"> on_command</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">cmd</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">ParsedCommand</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> session</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">Session</span><span style="color:#89DDFF;">)</span><span style="color:#89DDFF;"> -&gt;</span><span style="color:#89DDFF;"> None:</span></span>
<span class="line"><span style="color:#BABED8;">    ...</span></span></code></pre></div><p>Use it when you want visibility into command execution without middleware wrapping.</p><h3 id="interrupt" tabindex="-1"><code>interrupt</code> <a class="header-anchor" href="#interrupt" aria-label="Permalink to &quot;\`interrupt\`&quot;">​</a></h3><p>Emitted when the prompt loop catches <code>KeyboardInterrupt</code>.</p><p>Handler shape:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#C792EA;">def</span><span style="color:#82AAFF;"> on_interrupt</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">session</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">Session</span><span style="color:#89DDFF;">)</span><span style="color:#89DDFF;"> -&gt;</span><span style="color:#89DDFF;"> None:</span></span>
<span class="line"><span style="color:#BABED8;">    ...</span></span></code></pre></div><h3 id="error" tabindex="-1"><code>error</code> <a class="header-anchor" href="#error" aria-label="Permalink to &quot;\`error\`&quot;">​</a></h3><p>Emitted when command execution raises an exception.</p><p>Handler shape:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#C792EA;">def</span><span style="color:#82AAFF;"> on_error</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">error</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> Exception</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> session</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">Session</span><span style="color:#89DDFF;">)</span><span style="color:#89DDFF;"> -&gt;</span><span style="color:#89DDFF;"> None:</span></span>
<span class="line"><span style="color:#BABED8;">    ...</span></span></code></pre></div><h3 id="exit" tabindex="-1"><code>exit</code> <a class="header-anchor" href="#exit" aria-label="Permalink to &quot;\`exit\`&quot;">​</a></h3><p>Emitted when the app is shutting down.</p><p>Handler shape:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#C792EA;">def</span><span style="color:#82AAFF;"> on_exit</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">session</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">Session</span><span style="color:#89DDFF;">)</span><span style="color:#89DDFF;"> -&gt;</span><span style="color:#89DDFF;"> None:</span></span>
<span class="line"><span style="color:#BABED8;">    ...</span></span></code></pre></div><h2 id="app-specific-hooks" tabindex="-1">App-Specific Hooks <a class="header-anchor" href="#app-specific-hooks" aria-label="Permalink to &quot;App-Specific Hooks&quot;">​</a></h2><p>Some app code also uses named hooks such as <code>state_migration</code>. These are not emitted by the general command loop in the same way, but they are still registered through the same event system and consumed by other framework components.</p><p>That means the bus is generic even though the main loop only emits a small set of lifecycle events.</p><h2 id="ordering" tabindex="-1">Ordering <a class="header-anchor" href="#ordering" aria-label="Permalink to &quot;Ordering&quot;">​</a></h2><p>Listeners run in registration order.</p><p>If you register:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#89DDFF;">@</span><span style="color:#82AAFF;">app</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">on</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">start</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#C792EA;">def</span><span style="color:#82AAFF;"> a</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">session</span><span style="color:#89DDFF;">):</span><span style="color:#BABED8;"> ...</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;">@</span><span style="color:#82AAFF;">app</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">on</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">start</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#C792EA;">def</span><span style="color:#82AAFF;"> b</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">session</span><span style="color:#89DDFF;">):</span><span style="color:#BABED8;"> ...</span></span></code></pre></div><p><code>a</code> runs before <code>b</code>.</p><h2 id="async-behavior" tabindex="-1">Async Behavior <a class="header-anchor" href="#async-behavior" aria-label="Permalink to &quot;Async Behavior&quot;">​</a></h2><p>Async listeners are awaited in sequence. Klix does not fan them out in parallel.</p><p>That makes behavior predictable, but it also means a slow listener delays later listeners.</p><h2 id="current-non-emitted-names" tabindex="-1">Current Non-Emitted Names <a class="header-anchor" href="#current-non-emitted-names" aria-label="Permalink to &quot;Current Non-Emitted Names&quot;">​</a></h2><p>You may see event names such as <code>resize</code>, <code>focus</code>, or <code>blur</code> mentioned in conceptual material. The event bus can represent them, but the current shipped app loop does not emit them automatically.</p><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ul><li>Using events when middleware would be a better fit for wrapping command execution.</li><li>Doing heavy blocking work in sync listeners.</li><li>Assuming every named event in the bus model is emitted by default.</li></ul><h2 id="related-reading" tabindex="-1">Related Reading <a class="header-anchor" href="#related-reading" aria-label="Permalink to &quot;Related Reading&quot;">​</a></h2><ul><li><a href="./middleware">Reference: Middleware</a></li><li><a href="./../concepts/events">Concepts: Events</a></li><li><a href="./../faq">FAQ</a></li></ul>`,53)])])}const D=e(l,[["render",t]]);export{F as __pageData,D as default};
